package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.text.InputType;import android.widget.*;import java.util.*;

/** One export workflow for documents, ranges and selections, with resumable jobs. */
final class NarrationOptions {
 static final int REQUEST=46;final ReaderActivity a;Bundle pending;SpeechProfile resumeChoice;NarrationOptions(ReaderActivity a){this.a=a;}
 String tr(String s){return AppLanguage.text(a,s);}void show(SpeechProfile voice){show(voice,null,a.chrome.current());}
 void show(SpeechProfile voice,String selection,int selectedPart){resumeChoice=voice;if(NarrationExportService.running){active();return;}int total=a.kind.equals("pdf")?a.pages:a.book!=null?a.book.chapters.size():1;if(total<1){toast("Aguarde o documento carregar.");return;}UiPanel panel=new UiPanel(a,"Guardar narração",null,"speaker");List<NarrationJob> jobs=NarrationJob.list(a,a.uri.toString());if(!jobs.isEmpty())panel.action("play","Retomar geração anterior",null,false,this::manage);if(selection!=null)panel.action("speaker","Guardar selecção",null,false,()->choose(voice,new ChapterRange(selectedPart,selectedPart,Math.max(total,selectedPart+1)),selection));else{panel.action("book",total==1?"Documento inteiro":"Livro inteiro",null,false,()->choose(voice,new ChapterRange(0,total-1,total),null));if(total>1){int current=Math.min(Math.max(0,a.chrome.current()),total-1);panel.action("bookmark",a.kind.equals("pdf")?"Página actual":"Capítulo actual",null,false,()->choose(voice,new ChapterRange(current,current,total),null));panel.action("contents",a.kind.equals("pdf")?"Escolher páginas":"Escolher capítulos",null,false,()->range(voice,current,total));}}panel.show();}
 void range(SpeechProfile voice,int current,int total){LinearLayout wrap=new LinearLayout(a);wrap.setOrientation(1);EditText first=new EditText(a),count=new EditText(a);first.setInputType(InputType.TYPE_CLASS_NUMBER);count.setInputType(InputType.TYPE_CLASS_NUMBER);first.setText(""+(current+1));count.setText(""+(total-current));wrap.addView(a.text("Começar na parte",13));wrap.addView(first);wrap.addView(a.text("Quantidade de partes",13));wrap.addView(count);UiDialog dialog=new UiDialog.Builder(a).setTitle("Intervalo de narração").setView(wrap).setPositiveButton("Continuar",null).setNegativeButton("Cancelar",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{ChapterRange range=ChapterRange.next(Integer.parseInt(first.getText().toString())-1,Integer.parseInt(count.getText().toString()),total);dialog.dismiss();choose(voice,range,null);}catch(Exception e){toast("Escolha um intervalo dentro do livro.");}});}
 void choose(SpeechProfile voice,ChapterRange range,String selection){LinearLayout wrap=new LinearLayout(a);wrap.setOrientation(1);wrap.addView(a.text("Formato de saída",14));RadioGroup mode=new RadioGroup(a);RadioButton parts=new RadioButton(a),single=new RadioButton(a);parts.setId(101);single.setId(102);parts.setText(tr("Um ficheiro por capítulo ou página"));single.setText(tr("Um único ficheiro"));parts.setTextColor(a.ink);single.setTextColor(a.ink);mode.addView(parts);mode.addView(single);mode.check(a.getSharedPreferences("seeky",0).getBoolean("narration_single",false)?102:101);wrap.addView(mode);wrap.addView(a.text("Tipo de ficheiro",14));RadioGroup kind=new RadioGroup(a);RadioButton mp3=new RadioButton(a),wav=new RadioButton(a);mp3.setId(201);wav.setId(202);mp3.setText(tr("MP3 · cerca de 10 vezes mais pequeno, para qualquer leitor"));wav.setText(tr("WAV · sem compressão"));mp3.setTextColor(a.ink);wav.setTextColor(a.ink);kind.addView(mp3);kind.addView(wav);kind.check(a.getSharedPreferences("seeky",0).getBoolean("narration_mp3",true)?201:202);wrap.addView(kind);SharedPreferences bg=a.getSharedPreferences("reading_background",0);CheckBox music=new CheckBox(a);music.setText(tr("Guardar com fundo"));music.setTextColor(a.ink);music.setEnabled(!bg.getString("path","").isEmpty());music.setChecked(bg.getBoolean("export",false)&&music.isEnabled());wrap.addView(music);TextView sample=a.button("Ouvir prévia de 30 segundos",()->new NarrationPreview(a,voice,range.first,selection,music.isChecked()).show());UiBox.style(sample);wrap.addView(sample);wrap.addView(a.text("O progresso fica guardado. Pode pausar e retomar sem gerar de novo os trechos concluídos.",12));new UiDialog.Builder(a).setTitle("Opções da narração").setView(wrap).setPositiveButton("Escolher pasta",(d,w)->{pending=new Bundle();pending.putString("engine",voice.engine);pending.putString("voice",voice.voice);pending.putString("language",voice.language);pending.putBoolean("online",voice.online);pending.putFloat("rate",voice.rate);pending.putInt("first",range.first);pending.putInt("last",range.last);pending.putBoolean("single",mode.getCheckedRadioButtonId()==102);pending.putBoolean("mp3",kind.getCheckedRadioButtonId()==201);a.getSharedPreferences("seeky",0).edit().putBoolean("narration_single",mode.getCheckedRadioButtonId()==102).putBoolean("narration_mp3",kind.getCheckedRadioButtonId()==201).apply();bg.edit().putBoolean("export",music.isChecked()).apply();if(music.isChecked()){pending.putString("background",bg.getString("path",""));pending.putInt("background_volume",bg.getInt("volume",15));}if(selection!=null)pending.putString("selection",selection);SpeechEvents.State active=SpeechEvents.state;if(active.active&&!active.paused)ReadAloudService.control(a,ReadAloudService.PAUSE,active.token);try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),REQUEST);}catch(Exception e){pending=null;toast(e.getMessage());}}).setNegativeButton("Cancelar",null).show();}
 void manage(){if(NarrationExportService.running){active();return;}List<NarrationJob> jobs=NarrationJob.list(a,a.uri.toString());if(jobs.isEmpty()){toast("Não há gerações por terminar neste livro.");return;}String[] labels=new String[jobs.size()];for(int n=0;n<jobs.size();n++){NarrationJob j=jobs.get(n);labels[n]=(j.s("book").isEmpty()?j.s("name"):j.s("book"))+" · "+tr("Parte")+" "+(j.i("part")+1)+" · "+j.i("saved")+(j.b("mp3")?" MP3":" WAV");}new UiDialog.Builder(a).setTitle("Retomar narração").setItems(labels,(d,n)->{NarrationJob job=jobs.get(n);new UiDialog.Builder(a).setTitle("Geração guardada").setMessage(labels[n]+(job.s("error").isEmpty()?"":"\n"+job.s("error"))).setPositiveButton("Retomar",(dialog,w)->{if(NarrationExportService.running){toast("Pause a geração em curso antes de retomar outra.");return;}try{notifications();a.startForegroundService(new Intent(a,NarrationExportService.class).setAction(NarrationExportService.START).putExtra("resume_job",job.id()));toast("A retomar da posição guardada…");}catch(Exception e){toast(e.getMessage());}}).setNeutralButton("Mais opções",(dialog,w)->jobOptions(job)).setNegativeButton("Fechar",null).show();}).setNegativeButton("Fechar",null).show();}
 void active(){new UiDialog.Builder(a).setTitle("Geração em curso").setMessage("O progresso será conservado ao pausar.").setPositiveButton("Pausar",(d,w)->NarrationExportService.pauseJob(a)).setNegativeButton("Fechar",null).show();}
 void jobOptions(NarrationJob job){if(NarrationExportService.running){toast("Pause a geração em curso.");return;}UiPanel panel=new UiPanel(a,"Geração guardada",null,"folder");panel.action("folder","Escolher outra pasta",null,false,()->{if(NarrationExportService.running){toast("Pause a geração em curso.");return;}pending=new Bundle();pending.putString("resume_job",job.id());try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),REQUEST);}catch(Exception e){pending=null;toast(e.getMessage());}});if(job.n("bytes")==0&&!job.b("ready")){if(!job.s("background").isEmpty())panel.action("audio","Retomar sem fundo",null,false,()->{if(NarrationExportService.running)return;job.put("background","");continueJob(job);});panel.action("speaker","Retomar com a voz seleccionada",null,false,()->{if(NarrationExportService.running)return;SpeechProfile choice=resumeChoice;if(choice==null){SharedPreferences prefs=a.getSharedPreferences("seeky",0);choice=new SpeechProfile(prefs.getString("speech_engine",GoogleVoiceSetup.GOOGLE),prefs.getString("speech_voice",""),prefs.getString("speech_language","pt"),prefs.getBoolean("speech_online",false),prefs.getFloat("speech_rate",1));}job.put("engine",choice.engine);job.put("voice",choice.voice);job.put("language",choice.language);job.put("online",choice.online);job.put("rate",choice.rate);job.put("frames",0);job.put("voice_rate",0);continueJob(job);});}panel.action("trash","Descartar parcial",null,true,()->new UiDialog.Builder(a).setTitle("Descartar esta geração?").setMessage("Só o áudio temporário será removido. Os ficheiros já guardados são conservados.").setPositiveButton("Descartar",(d,w)->{if(!NarrationExportService.running){job.discard();BackgroundSettings.prune(a);}}).setNegativeButton("Cancelar",null).show());panel.show();}
 void continueJob(NarrationJob job){try{job.save();notifications();a.startForegroundService(new Intent(a,NarrationExportService.class).setAction(NarrationExportService.START).putExtra("resume_job",job.id()));}catch(Exception e){toast(e.getMessage());}}
 void notifications(){if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},47);}
 void result(int request,int result,Intent data){if(request!=REQUEST)return;Bundle chosen=pending;pending=null;if(result!=Activity.RESULT_OK||data==null||data.getData()==null||chosen==null)return;try{Uri tree=data.getData();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new IllegalStateException(tr("A pasta não permite gravar."));try{a.getContentResolver().takePersistableUriPermission(tree,flags);}catch(SecurityException ignored){}notifications();if(chosen.containsKey("resume_job")){NarrationJob job=NarrationJob.load(a,chosen.getString("resume_job"));job.put("tree",tree.toString());job.put("folder","");job.put("pending_uri","");job.save();a.startForegroundService(new Intent(a,NarrationExportService.class).setAction(NarrationExportService.START).putExtra("resume_job",job.id()));toast("A retomar na nova pasta…");return;}a.startForegroundService(new Intent(a,NarrationExportService.class).setAction(NarrationExportService.START).setDataAndType(a.uri,a.mime).putExtras(chosen).putExtra("name",a.name).putExtra("display_title",a.getIntent().getStringExtra("study_title")).putExtra("tree",tree.toString()));toast("A gerar narração. Acompanhe na notificação.");}catch(Exception e){toast(e.getMessage());}}
 void save(Bundle out){if(pending!=null)out.putBundle("narration_options",pending);}void restore(Bundle state){if(state!=null)pending=state.getBundle("narration_options");}void toast(String text){Toast.makeText(a,tr(text==null?"Não foi possível iniciar a narração.":text),Toast.LENGTH_LONG).show();}
}
